"""Closed formulas of Section "Computing Mayer Path Homology when N = 3".

For a digraph G = (V, E) (self-loops and opposite edges allowed, non-regular
boundary) and N = 3:

* square classes: the equivalence relation on V generated by i ~ j whenever i and
  j are the middle vertices of a square e_{kil} - e_{kjl} in Omega_2 (that is,
  (k,i), (k,j), (i,l), (j,l) in E and (k,l) not in E; k = l allowed);
  C = V / ~;
* triangles: Delta = {(i,j,k) : (i,j), (j,k), (i,k) in E} (vertices need not be
  distinct);
* T : K^C -> K^Delta,  (T F)_{(i,j,k)} = F([k]) + xi F([j]) + xi^2 F([i]).

Proposition (rank of d^2 on Omega_2):  rank(d1 d2 |Omega_2) = |V| - |C| + rank T.
Corollary:
    beta_0^{3,1} = |C| - rank T,
    beta_2^{3,2} = dim Omega_2 - |V| + |C| - rank T - rank(d_3 |Omega_3).
Also  dim Omega_2 = |Delta| + sum_{(k,l) not in E, m_kl >= 1} (m_kl - 1),
where m_kl is the number of middle vertices of (k, l).
"""
from __future__ import annotations

from collections import defaultdict
from typing import Dict, Hashable, Iterable, List, Tuple

import numpy as np

from .core import rank, root_of_unity


def middle_vertices(vertices: Iterable[Hashable], edges: Iterable[Tuple]) -> Dict[Tuple, List]:
    """m(k, l) = {v : (k, v), (v, l) in E} for every pair with at least one middle vertex."""
    out = defaultdict(set)
    for a, b in edges:
        out[a].add(b)
    mids = defaultdict(list)
    for k in out:
        for v in out[k]:
            for l in out.get(v, ()):
                mids[(k, l)].append(v)
    return {kl: sorted(vs, key=str) for kl, vs in mids.items()}


def triangles(edges: Iterable[Tuple]) -> List[Tuple]:
    """Delta = {(i, j, k) : (i,j), (j,k), (i,k) in E}."""
    E = set(edges)
    out = defaultdict(set)
    for a, b in E:
        out[a].add(b)
    return sorted(((i, j, k) for i in out for j in out[i] for k in out.get(j, ()) if (i, k) in E), key=str)


def omega2_dim(vertices, edges) -> int:
    """dim Omega_2^N = |Delta| + sum over non-edges (k,l) of (m_kl - 1)."""
    E = set(edges)
    mids = middle_vertices(vertices, E)
    return len(triangles(E)) + sum(len(m) - 1 for kl, m in mids.items() if kl not in E)


def square_classes(vertices: Iterable[Hashable], edges: Iterable[Tuple]) -> Dict[Hashable, int]:
    """Class index [v] of every vertex under the relation generated by the squares."""
    V = list(vertices)
    E = set(edges)
    parent = {v: v for v in V}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for kl, ms in middle_vertices(V, E).items():
        if kl in E:
            continue                       # triangles, no identification
        for v in ms[1:]:
            ra, rb = find(ms[0]), find(v)
            if ra != rb:
                parent[ra] = rb
    roots = {}
    return {v: roots.setdefault(find(v), len(roots)) for v in V}


def triangle_matrix(vertices, edges, N: int = 3) -> np.ndarray:
    """Matrix of T : K^C -> K^Delta (rows: triangles, columns: square classes)."""
    cls = square_classes(vertices, edges)
    tri = triangles(edges)
    xi = root_of_unity(N)
    T = np.zeros((len(tri), len(set(cls.values()))), complex)
    for r, (i, j, k) in enumerate(tri):
        T[r, cls[k]] += 1.0
        T[r, cls[j]] += xi
        T[r, cls[i]] += xi ** 2
    return T


def rank_d2_on_omega2(vertices, edges, N: int = 3) -> int:
    """rank(d1 d2 | Omega_2) = |V| - |C| + rank T   (Proposition, N = 3)."""
    V = list(vertices)
    n_classes = len(set(square_classes(V, edges).values()))
    return len(V) - n_classes + rank(triangle_matrix(V, edges, N))


def betti0_31(vertices, edges) -> int:
    """beta_0^{3,1} = |C| - rank T   (Corollary)."""
    V = list(vertices)
    return len(set(square_classes(V, edges).values())) - rank(triangle_matrix(V, edges, 3))


def betti2_32(vertices, edges, rank_d3_on_omega3: int) -> int:
    """beta_2^{3,2} = dim Omega_2 - |V| + |C| - rank T - rank(d_3 | Omega_3)   (Corollary)."""
    V = list(vertices)
    return omega2_dim(V, edges) - rank_d2_on_omega2(V, edges, 3) - rank_d3_on_omega3
